(function(){'use strict';const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e,el=k=>document.getElementById('M10-'+k);if(!el('plot'))return;
const defaults={algorithm:'Momentum',lr:.07,beta:.6,steps:12};let p={...defaults},timer=null;
function trace(){let x=3,y=1,vx=0,vy=0,mx=0,my=0,sx=0,sy=0;const a=[{x,y}];for(let t=1;t<=p.steps;t++){const gx=x,gy=25*y;if(p.algorithm==='Adam'){mx=.9*mx+.1*gx;my=.9*my+.1*gy;sx=.999*sx+.001*gx*gx;sy=.999*sy+.001*gy*gy;x-=p.lr*(mx/(1-.9**t))/(Math.sqrt(sx/(1-.999**t))+1e-8);y-=p.lr*(my/(1-.9**t))/(Math.sqrt(sy/(1-.999**t))+1e-8);}else{vx=(p.algorithm==='Momentum'?p.beta:0)*vx+gx;vy=(p.algorithm==='Momentum'?p.beta:0)*vy+gy;x-=p.lr*vx;y-=p.lr*vy;}a.push({x,y});if(Math.max(Math.abs(x),Math.abs(y))>1e12)break;}return a;}
function state(){const a=trace(),r=a.at(-1);return {...p,x:r.x,y:r.y,loss:.5*(r.x*r.x+25*r.y*r.y),actualSteps:a.length-1,outsideView:a.filter(r=>Math.abs(r.x)>4||Math.abs(r.y)>2).length};}
function draw(){const a=trace(),s=state(),X=x=>460+x*95,Y=y=>205-y*80;el('algorithm').value=p.algorithm;for(const k of ['lr','beta','steps']){el(k).value=p[k];el(k+'-value').textContent=k==='steps'?p[k]:p[k].toFixed(3);}let h='<defs><clipPath id="M10-clip"><rect x="80" y="45" width="760" height="320"/></clipPath></defs>';
for(const v of [.05,.2,.5,1,2,4,8,16,32])h+=`<ellipse cx="460" cy="205" rx="${Math.sqrt(2*v)*95}" ry="${Math.sqrt(2*v/25)*80}" fill="none" stroke="#ccd5dc" clip-path="url(#M10-clip)"/>`;
for(const x of [-4,-2,0,2,4])h+=`<text x="${X(x)}" y="389" text-anchor="middle" fill="currentColor">${x}</text>`;for(const y of [-2,-1,0,1,2])h+=`<text x="65" y="${Y(y)+5}" text-anchor="end" fill="currentColor">${y}</text>`;
h+=`<g clip-path="url(#M10-clip)"><path d="${a.map((r,j)=>(j?'L':'M')+X(r.x)+','+Y(r.y)).join(' ')}" fill="none" stroke="#0072B2" stroke-width="2.4"/>`;for(const r of a)h+=`<circle cx="${X(r.x)}" cy="${Y(r.y)}" r="3.5" fill="#0072B2"/>`;h+='</g><circle cx="460" cy="205" r="5" fill="#D58500"/>';
h+=`<text x="460" y="415" text-anchor="middle" fill="currentColor">${tr('参数 x','Parameter x')}</text><text x="80" y="24" fill="currentColor">${tr('参数 y；目标等高线','Parameter y; objective contours')}</text>`;el('plot').innerHTML=h;
const f=v=>Math.abs(v)>1e5?v.toExponential(3):v.toFixed(5);el('result').textContent=tr(`已计算${s.actualSteps}步：x=${f(s.x)}，y=${f(s.y)}，损失=${f(s.loss)}；${s.outsideView}个点位于当前坐标范围之外。`,`${s.actualSteps} updates: x=${f(s.x)}, y=${f(s.y)}, loss=${f(s.loss)}; ${s.outsideView} points lie outside the displayed coordinate range.`);}
function set(v){if(['SGD','Momentum','Adam'].includes(v.algorithm))p.algorithm=v.algorithm;if(Number.isFinite(Number(v.lr)))p.lr=Math.max(.001,Math.min(.2,+v.lr));if(Number.isFinite(Number(v.beta)))p.beta=Math.max(0,Math.min(.95,+v.beta));if(Number.isFinite(Number(v.steps)))p.steps=Math.max(0,Math.min(60,Math.round(+v.steps)));draw();return state();}
function stop(){if(timer)clearInterval(timer);timer=null;el('play').textContent=tr('播放','Play');}function reset(){stop();p={...defaults};draw();return state();}
for(const k of Object.keys(p))el(k).addEventListener('input',()=>{stop();set({[k]:el(k).value});});el('step').addEventListener('click',()=>{stop();set({steps:p.steps+1});});el('play').addEventListener('click',()=>{if(timer){stop();return;}if(p.steps>=60)p.steps=0;el('play').textContent=tr('暂停','Pause');timer=setInterval(()=>{set({steps:p.steps+1});if(p.steps>=60||state().actualSteps<p.steps)stop();},300);});el('reset').addEventListener('click',reset);window.CourseLab={state,set,reset,destroy:stop};draw();})();
